"use client"

import animation from "react-useanimations/lib/wifi"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "WiFi" from https://useanimations.com (MIT): https://useanimations.com/icons/wifi
export function AnimatedWifi(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover-replay"
      {...props}
    />
  )
}
